import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Filter out derived features for driver selection
    non_derived_mask = [t != 'derived' for t in feats.types]
    non_derived_ids = [fid for i, fid in enumerate(feats.ids) if non_derived_mask[i]]

    # Compute correlations between all pairs of non-derived features
    corr_matrix = np.corrcoef(feats.x[:, [feats.column(fid) for fid in non_derived_ids]].T)

    # Identify near-duplicates (correlation >= 0.6)
    near_duplicates = set()
    for i in range(len(non_derived_ids)):
        for j in range(i+1, len(non_derived_ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                near_duplicates.add((non_derived_ids[i], non_derived_ids[j]))

    # Select top features by t-statistic (excluding near-duplicates)
    drivers = []
    used_ids = set()

    # Sort features by absolute t-statistic
    t_stats = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue
        col_idx = feats.column(fid)
        y0 = feats.x[feats.y==0, col_idx]
        y1 = feats.x[feats.y==1, col_idx]
        if len(y0) > 0 and len(y1) > 0:
            t_stat, _ = stats.ttest_ind(y1, y0)
            t_stats.append((abs(t_stat), fid))

    t_stats.sort(reverse=True)

    # Add features to drivers, avoiding near-duplicates
    for _, fid in t_stats:
        if fid in used_ids:
            continue
        # Check if any near-duplicate is already selected
        skip = False
        for dup1, dup2 in near_duplicates:
            if (fid == dup1 and dup2 in used_ids) or (fid == dup2 and dup1 in used_ids):
                skip = True
                break
        if not skip:
            drivers.append(fid)
            used_ids.add(fid)
            if len(drivers) >= MAX_DRIVERS:
                break

    # Build columns list (include all non-derived features that aren't near-duplicates)
    columns = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue
        col_idx = feats.column(fid)
        # Check if this feature or its duplicates are already in drivers
        skip = False
        for dup1, dup2 in near_duplicates:
            if (fid == dup1 and dup2 in drivers) or (fid == dup2 and dup1 in drivers):
                skip = True
                break
        if not skip:
            columns.append(fid)

    # Create products from driver pairs (avoiding near-duplicates)
    products = []
    for i, d1 in enumerate(drivers):
        for d2 in drivers[i+1:]:
            # Check if they are near-duplicates
            is_dup = any((d1 == a and d2 == b) or (d1 == b and d2 == a) 
                        for a, b in near_duplicates)
            if not is_dup:
                products.append((d1, d2))

    # Create loadings for weighted score
    loadings = {}
    for fid in columns:
        col_idx = feats.column(fid)
        # Use standardized coefficient from simple linear regression with outcome
        x = feats.x[:, col_idx]
        y = feats.y.astype(float)
        if np.std(x) > 0:
            # Simple linear regression coefficient (scaled by std dev)
            loading = np.corrcoef(x, y)[0,1] * np.std(x) / np.std(y)
            loadings[fid] = loading

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )
